WFI.Data.add("quest", {
  [6001] = { "Corpo e cuore", "Usa la Cenarion Moondust sulla Moonkin Stone di Auberdine per far comparire Lunaclaw. Poi dovrai affrontare Lunaclaw e conquistare la forza del corpo e del cuore che possiede.\n\nQuando hai finito, parla con Mathrengyl Bearwalker, a Darnassus.", "Proprio a est di Auberdine ci sono molte caverne dei moonkin. In quella più vicina ad Auberdine c'è una Moonkin Stone. Lunaclaw, il difensore della pietra, ti affronterà solo quando ci verrà sparsa sopra la Cenarion Moondust. Lunaclaw ha dentro di sé una forza che devi usare come membro dell'artiglio.\n\nTi sei <guadagnato/guadagnata> il diritto di usare questa Cenarion Moondust, {name}... ora dimostrami di esserti <guadagnato/guadagnata> il diritto di possedere la forza del corpo e la forza del cuore che servono a un druido!", "Quando avrai affrontato la sfida che ti attende, capirai fino in fondo la forza del corpo e la forza del cuore. Fino ad allora, non posso aiutarti oltre.", "Hai finalmente fatto il tuo grande passo in un mondo molto più grande, {name}. Sento in te l'insegnamento del Great Bear Spirit, e sento che hai ricevuto la forza che possedeva Lunaclaw.\n\nNon ci sono più ostacoli sulla tua strada... lascia che ora ti insegni cosa vuol dire essere un Druid of the Claw!", 0x9109866f, 0xe7d92ce2, 0xd25471ff, 0xf431a09c, 0x5233b46d, "....." },
  [6002] = { "Corpo e cuore", nil, nil, "Quando avrai affrontato la sfida che ti attende, capirai fino in fondo la forza del corpo e la forza del cuore. Fino ad allora, non posso aiutarti oltre.", "Hai finalmente fatto il tuo grande passo in un mondo molto più grande, {name}. Sento in te l'insegnamento del Great Bear Spirit, e sento che hai ricevuto la forza che possedeva Lunaclaw.\n\nNon ci sono più ostacoli sulla tua strada... lascia che ora ti insegni cosa vuol dire essere un Druid of the Claw!", 0x9109866f, nil, nil, 0xf431a09c, 0x5233b46d, ".mm.." },
  [6061] = { "Domare la bestia", nil, nil, nil, nil, 0xecd97a9a, nil, nil, nil, nil, ".mmmm" },
  [6062] = { "Domare la bestia", nil, nil, nil, nil, 0xecd97a9a, nil, nil, nil, nil, ".mmmm" },
  [6063] = { "Domare la bestia", "Usa la Taming Rod per domare un Webwood Lurker. Esercitati, poi riporta la Taming Rod a Dazalar, a Dolanaar.", "Da cacciatore, è importante ricordare la responsabilità che hai tra le mani. La natura non è un potere che si può piegare ai nostri desideri; va rispettata e riconosciuta come qualcosa di più forte della tua stessa esistenza.\n\n{name}, devi dimostrare di averlo capito prima di ottenere la capacità di domare un animale come compagno.\n\nIl tuo primo compito è prendere questa Taming Rod. Con essa potrai domare un webwood lurker. Domalo ed esercita le tue abilità di cacciatore.", "Imparerai, {name}, e un giorno sarai <un/una> grande <cacciatore/cacciatrice>.", "Eccellente, {name}! Impari davvero in fretta.", 0xecd97a9a, 0x72db5042, 0x39ad25e9, 0x407acae4, 0x7f1a8496, "....." },
  [6064] = { "Domare la bestia", nil, nil, nil, nil, 0xecd97a9a, nil, nil, nil, nil, ".mmmm" },
  [6065] = { "La via del cacciatore", nil, nil, nil, nil, 0xe59cef47, nil, nil, nil, nil, ".mmmm" },
