  [6101] = { "Domare la bestia", "Usa la Taming Rod per domare un Nightsaber Stalker. Esercitati, poi riporta la Taming Rod a Dazalar, a Dolanaar.", "Sulla varietà della natura si può contare, {name}. È prevedibile nel senso che non resta mai uguale: cambia sempre.\n\nI compiti che ti affido ti aiuteranno a vedere e apprezzare le grandi differenze tra le creature che potresti scegliere come compagne.\n\nPrendi questa Taming Rod e usala per domare un nightsaber stalker, che trovi a sud. Esercita le tue abilità di cacciatore. Allora comincerai a capire le somiglianze e le differenze della natura.", "Capire l'equilibrio tra la natura e se stessi è uno stile di vita per ogni elfo della notte.", "Vedo il tuo impegno, e vedo che hai capito quello che ti ho insegnato, {name}.", 0xecd97a9a, 0xd54ea322, 0x4cf39634, 0x2bb052d9, 0xe3639023, "....." },
  [6102] = { "Domare la bestia", "Usa la Taming Rod per domare uno Strigid Screecher. Esercitati, poi riporta la Taming Rod a Dazalar, a Dolanaar.", "Hai domato due creature che abitano la terra, ora devi domarne una che solca i cieli. Usa la Taming Rod per domare uno strigid screecher, che trovi a ovest di qui. Esercita le tue abilità con questo possente gufo al tuo fianco.\n\nQuando tornerai, ti darò le abilità che ti serviranno per domare un animale a tua scelta come compagno; questa creatura affronterà le tue stesse sfide e acquisirà esperienza insieme a te. Ti mostrerò anche come chiamarla e congedarla quando vuoi.", "Sono fiero dei tuoi risultati, {name}. Hai finito l'ultimo compito che ti ho dato?", "Hai imparato tutto quello che potevo insegnarti, {name}. Lascia che ti dia un ultimo consiglio: scegli con giudizio il tuo primo animale. Sceglierai una creatura della terra, dell'acqua o del cielo? Qualunque sia, il tuo animale resterà con te per parecchio tempo, senza dubbio.\n\nEcco, {name}. Ora ti darò il potere di domare una bestia, e di chiamarla e congedarla come ritieni meglio. Usa con orgoglio le tue nuove abilità; te le sei guadagnate.", 0xecd97a9a, 0xe53bb451, 0x3445b668, 0xc9470946, 0xdeb475c1, "....." },
  [6103] = { "Addestrare la bestia", "Parla con Jocaste, nel Cenarion Enclave, a Darnassus.", "Ora hai il potere di domare un animale, ma devi anche acquisire le abilità per addestrarlo.\n\nVai a Darnassus. Lì devi parlare con una delle nostre cacciatrici più venerate, Jocaste. Ti darà la capacità di addestrare il tuo nuovo animale, quindi sbrigati.\n\nJocaste può sembrare severa, ma è sempre contenta di vedere un altro cacciatore salire di grado. Trattala con rispetto e lei ti ricambierà. Buona fortuna, {name}.", nil, "<Un/Una> <cacciatore/cacciatrice> alle prime armi, vedo. Sì, posso darti le abilità che ti servono per addestrare e guidare il tuo animale. Non solo potrai insegnargli nuove abilità, ma ora potrai anche nutrirlo e rianimarlo, se dovesse cadere in battaglia.\n\nRicorda, {name}: rispetta sempre l'equilibrio e vivi in ammirazione della natura che ti circonda. Ora vai. Ci parleremo di nuovo, più avanti.", 0xdbeedc0e, 0x6e901431, 0x3d135ae6, nil, 0xce7253c1, "...m." },
  [6121] = { "Nuove lezioni", "Vai a Moonglade e parla con Dendrite Starblaze nel villaggio di Nighthaven.", "Ora sei <pronto/pronta> a imparare cosa sono i veleni e il potere che noi druidi abbiamo su di essi, {name}. Cenarius ci ha concesso la capacità di eliminare anche i veleni più immondi con un semplice incantesimo. Questo dono non va preso alla leggera... e perché tu impari bene la lezione, affronterai gli effetti degli avvelenamenti come farebbe una persona qualunque.\n\nVai a Moonglade e parla con Dendrite Starblaze; aspetta il tuo arrivo per cominciare la lezione.", nil, "Salute, giovane druido, sono felice di vederti <pronto/pronta> e <desideroso/desiderosa> di imparare a curare i veleni.\n\nIn passato quasi tutti i druidi venivano sottoposti a prove preparate in anticipo, ma per te non sarà così. Ad Auberdine c'è stata un'ondata di avvelenamenti di animali, e il villaggio non è riuscito a curarli. Per questo un loro rappresentante ha chiesto aiuto a Moonglade, e noi mandiamo te ad aiutarli. Non è un esercizio: il lavoro che farai è del tutto reale. Tienilo a mente.", 0xe3814355, 0xb25e3d68, 0x738324f8, nil, 0xe3b1d128, "...m." },
  [6122] = { "La fonte principale", "Usa l'Empty Cliffspring Falls Sampler per prelevare un campione d'acqua all'imboccatura della grotta presso le cascate.\n\nConsegna il Filled Cliffspring Falls Sampler ad Alanndarian Nightsong, ad Auberdine, Darkshore.", "Le Cliffspring Falls di Darkshore sono la fonte principale di acqua potabile della regione, e ora sospetto che siano anche la fonte principale del veleno che danneggia la fauna locale, i cervi in particolare. Usa questo campionatore per prelevare un po' d'acqua all'imboccatura della grotta; fa' attenzione, perché ora pericolosi naga abitano una grotta presso le cascate.\n\nUna volta pieno, consegnalo ad Alanndarian Nightsong, ad Auberdine. È lei che ha chiesto il nostro aiuto, e lavorerai con lei per affrontare questo male.", "Sei tu la persona che ha mandato il Cenarion Circle di Moonglade? Magnifico! Qui abbiamo una bella crisi tra le mani riguardo ai poveri cervi, e siamo felici di ogni aiuto possibile.\n\nHai il campione d'acqua che Dendrite Starblaze ha detto che avresti avuto? Mi ha avvisato che ne avresti prelevato uno perché potessimo lavorare insieme a una cura...", "Per Elune, quest'acqua è disgustosa! Non c'è da stupirsi che i cervi siano malati.\n\nQualcosa inquina l'acqua e, di conseguenza, corrompe l'intera falda di Darkshore. Cervi malati sono stati visti in tutta la zona, e non solo vicino al fiume. Anche se quest'acqua è molto probabilmente una fonte primaria della malattia che si diffonde, c'è qualcos'altro all'opera qui.\n\nQuest'acqua, che tu ci creda o no, ci aiuterà a preparare una cura. Mentre la studio, mi servono alcuni oggetti per formularla...", 0xfe91905d, 0xed0bc128, 0xe6b38f20, 0x7f300676, 0xc7a9f8eb, "....." },
  [6123] = { "Raccogliere la cura", "Porta 5 Earthroot e 12 Lunar Funguses ad Alanndarian Nightsong, ad Auberdine, perché possa preparare un unguento curativo.", "L'acqua farà da base all'unguento curativo che preparerò per i cervi. Per le proprietà curative mi serve dell'earthroot. Gli erboristi sanno come trovarla, quindi se siamo sfortunati e tu non lo sei, dovrai trovarne uno che ci aiuti.\n\nInfine, per la potenza, mi serve del lunar fungus. Trovare le fioriture di lunar fungus è abbastanza facile: sono dappertutto nelle caverne appena a est di qui. Nelle caverne vivono i moonkin, e ultimamente sono irritabili, quindi stai <attento/attenta>.", "Hai i reagenti che mi servono per preparare l'unguento? I cervi non migliorano da soli, quindi è meglio sbrigarsi ad aiutarli!", "Ottimo, {name}, tanto che dovrebbe bastare a preparare dosi abbondanti dell'unguento, almeno abbastanza da cominciare a fare la differenza.\n\nPreparare una cura per i veleni a volte può essere piuttosto difficile, perché ognuno richiede spesso un antidoto molto specifico per contrastarlo. Immagina di poter curare un veleno a piacimento senza doverti preoccupare degli ingredienti esatti dell'antidoto!\n\nOra lasciami mettere al lavoro!", 0xc0a4b4dc, 0x14a92d63, 0xd43adcc8, 0xd5399fb4, 0x0d585714, "....." },
  [6124] = { "Curare i malati", "Usa il Curative Animal Salve su 10 Sickly Deer sparsi per Darkshore; così dovresti curarli. I Sickly Deer sono stati avvistati a partire da sud del Cliffspring River, a nord di Auberdine, fino alla parte meridionale di Darkshore, dove comincia Ashenvale.", "L'unguento ricavato dai reagenti che mi hai portato basta per dieci dosi, {name}. Mentre lavoro con il villaggio per prepararne dell'altro, vorrei che ci aiutassi a portarci avanti. In tutta Darkshore ci sono cervi malati; usa l'unguento su di loro e cura il loro malessere.\n\nDi sicuro Dendrite Starblaze, a Moonglade, vorrà parlarti quando avrai finito. Ti prego, porta i ringraziamenti di Auberdine al Cenarion Circle laggiù... e lascia che ti ringrazi io stessa per l'aiuto che ci hai dato!", "Hai portato a termine ciò che ti ha chiesto Alanndarian Nightsong di Auberdine? Il tuo lavoro non è concluso finché non l'avrai fatto.", "Hai fatto bene a curare i cervi malati di Darkshore; sono vittime inconsapevoli di una contaminazione e di una corruzione più grandi che si stanno diffondendo in tutta la terra. A Darnassus c'è chi sceglie di riconoscere questa minaccia... e chi ignora i segnali crescenti. Spero che tu non sia tra quelli che si mettono i paraocchi davanti ai fatti evidenti, {name}.\n\nAd ogni modo, hai dimostrato il tuo valore come <amico/amica> della natura e del Circle: prendi questo come simbolo.", 0x0116fddd, 0x20fba3fe, 0xbc2e713b, 0xb12ec810, 0x848c8bee, "....." },
  [6125] = { "Potere sul veleno", "Torna da Mathrengyl Bearwalker, nel Cenarion Enclave, a Darnassus.", "Hai imparato cosa significa curare un veleno senza il beneficio dell'aiuto spirituale. Ricorda ciò che altri devono sopportare nel combattere le afflizioni velenose, mentre presto abbraccerai il tuo nuovo potere sul veleno.\n\nOra dovresti tornare da Mathrengyl Bearwalker, a Darnassus, {name}. Senza dubbio ha un incantesimo molto importante da insegnarti, ora che l'allievo ha compreso la lezione che <gli/le> è stata impartita.\n\nAddio, giovane <druido/druida>. Ci parleremo di nuovo.", nil, "<Bentornato/Bentornata>. Ho seguito i tuoi progressi in questa lezione da quando sei <partito/partita>, e devo ammettere che sono rimasto sorpreso nell'apprendere della situazione ad Auberdine. Merita ulteriori indagini, perché l'introduzione di simili veleni nell'ambiente turba moltissimo l'equilibrio.\n\nTi sei <comportato/comportata> con grazia sotto pressione. Per questo non trovo modo migliore di ricompensarti che con un potere permanente sul veleno. Usalo bene, {name}... usalo bene.", 0xfaefb521, 0x6562a80b, 0xe76f8205, nil, 0x02ded2c7, "...m.", nil, nil, 0xe5d51b88, nil, nil },
  [6126] = { "Nuove lezioni", "Vai a Moonglade e parla con Dendrite Starblaze nel villaggio di Nighthaven.", "Ora sei <pronto/pronta> a imparare cosa sono i veleni e il potere che noi druidi abbiamo su di essi, {name}. Cenarius ci ha concesso la capacità di eliminare anche i veleni più immondi con un semplice incantesimo. Questo dono non va preso alla leggera... e perché tu impari bene la lezione, affronterai gli effetti degli avvelenamenti come farebbe una persona qualunque.\n\nVai a Moonglade e parla con Dendrite Starblaze; aspetta il tuo arrivo per cominciare la lezione.", nil, nil, 0xe3814355, 0xb25e3d68, 0x738324f8, nil, nil, "...mm" },
  [6127] = { "La fonte principale", nil, nil, nil, nil, 0xfe91905d, nil, nil, nil, nil, ".mmmm" },
  [6128] = { "Raccogliere la cura", nil, nil, nil, "Ottimo, {name}, tanto che dovrebbe bastare a preparare dosi abbondanti dell'unguento, almeno abbastanza da cominciare a fare la differenza.\n\nPreparare una cura per i veleni a volte può essere piuttosto difficile, perché ognuno richiede spesso un antidoto molto specifico per contrastarlo. Immagina di poter curare un veleno a piacimento senza doverti preoccupare degli ingredienti esatti dell'antidoto!\n\nOra lasciami mettere al lavoro!", 0xc0a4b4dc, nil, nil, nil, 0x0d585714, ".mmm." },
  [6129] = { "Curare i malati", nil, nil, nil, nil, 0x0116fddd, nil, nil, nil, nil, ".mmmm" },
  [6130] = { "Potere sul veleno", nil, nil, nil, nil, 0xfaefb521, nil, nil, nil, nil, ".mmmm" },
  [6161] = { nil, nil, nil, "Questo forziere è chiuso a chiave saldamente.", nil, nil, nil, nil, 0x24ee971a, nil, "mmm.m" },
  [6181] = { "Un messaggio rapido", "Porta la Lewis' Note a Thor, il maestro dei grifoni.", "Anche se da Stormwind non riceviamo molti aiuti diretti, ho un contatto in città che ci aiuta a rifornirci di armature. Si chiama Osric Strang. La sua bottega, Limited Immunity, è nella Old Town di Stormwind.\n\nLe nostre scorte di armature si assottigliano, e devo chiedere a Osric di mandarcene altre. Puoi portargli questo biglietto?\n\nIl modo più rapido per arrivare a Stormwind è Thor, il nostro maestro dei grifoni. È appena giù per la collina: portagli il mio biglietto, poi prendi un grifone per Stormwind.", "Sembri <uno/una> che va di fretta. Be', allora sei nel posto giusto!", "Devi portare questo biglietto a Stormwind? Nessun problema, puoi prendere uno dei miei grifoni!", 0xd0027ff1, 0xacee0705, 0x971b5160, 0x5c4d4ffe, 0x13821bcd, "....." },
  [6281] = { "Proseguire per Stormwind", "Compra un volo in grifone dal maestro dei grifoni Thor, poi porta la Lewis' Note a Osric Strang, nella bottega Limited Immunity, nella Old Town di Stormwind.", "Per una piccola somma puoi prendere un grifone per Stormwind, così potrai consegnare il biglietto di Lewis a Osric. In nessun altro modo arriverai prima.\n\nSe ti sta bene, parlami di nuovo quando sei <pronto/pronta> per il volo. Ti chiederò qualcosa, ma fidati: ne varrà la pena!", "Sei in viaggio, eh? Sei <stato/stata> in qualche posto interessante?", "Ah, un biglietto da Quartermaster Lewis? Non mi stupisce che gli serva altra attrezzatura. Sentinel Hill è lontana, in una terra che Stormwind ha quasi dimenticato.\n\nBe', grazie, {name}. Ecco un po' di denaro per coprire le spese di viaggio.", 0x950eaddd, 0x9a2be79a, 0xd7241ffb, 0xd55888b8, 0x83dfa7ed, "....." },
  [6341] = { "I doni di Teldrassil", "Porta la Nessa's Collection a Vesprystus.", "I pescatori del villaggio di Rut'theran se la cavano molto bene, perché qui i pesci sono enormi e abbondanti. Vorrei confrontare i doni di questo posto con quelli della terraferma.\n\nHo una collezione di lische e scaglie di pesce che vorrei far arrivare a un mio collega a Darkshore. Si chiama Laird ed è un pescivendolo del villaggio di Auberdine.\n\nPorta la mia collezione al nostro maestro degli ippogrifi, Vesprystus, e parlagli del viaggio verso Auberdine.", "Come posso aiutarti? Ti serve un passaggio?", "Ah, vuoi portarlo ad Auberdine? Molto bene...", 0xfdaa45cb, 0x849cfb5d, 0xeffe6b5d, 0x2fd3c26c, 0x82c592b4, "....." },
  [6342] = { "In volo verso Auberdine", "Vola su un ippogrifo fino ad Auberdine con il maestro degli ippogrifi Vesprystus, poi porta la Nessa's Collection a Laird.", "Da Rut'theran ci sono due modi per andare ad Auberdine: in traghetto e in ippogrifo. Sono entrambi rapidi e affidabili, ma se non hai ancora volato ad Auberdine in ippogrifo, ti consiglio di farlo.\n\nÈ un buon consiglio parlare con il maestro degli ippogrifi in ogni città che ne ha uno. Una volta che gli hai parlato, potrai volare lì anche da altre città.\n\nEcco la collezione di Nessa. Parlami di nuovo quando sarai <pronto/pronta> a volare ad Auberdine e a consegnare la collezione di Nessa a Laird.", "Vieni da Teldrassil? Dimmi, com'è la pesca laggiù?", "Un pacco da Nessa? Grazie, {name}! Mi aveva detto che mi avrebbe mandato dei campioni dei pesci pescati vicino al villaggio di Rut'theran. Pensa che potrebbero essere molto diversi da quelli pescati qui...\n\nAccidenti! Questa mascella è grande quasi il doppio di quella dello stesso pesce che si trova qui. E queste scaglie sono grandi come un pugno chiuso! Incredibile!", 0xdcb4055c, 0xedfc0608, 0xf7020ff1, 0x289d443c, 0xa33b905a, "....." },
  [6343] = { "Ritorno da Nessa", "Porta la Laird's Response a Nessa Shadowsong.", "Devo mandare una risposta a Nessa. Le interesserà molto sapere quanto sono diversi i pesci di qui da quelli lungo la costa di Teldrassil. Possiamo solo fare ipotesi sulla causa, ma sospetto che sia l'albero del mondo stesso a influire sulla fauna intorno a lui!\n\nTi prego, porta questa risposta a Nessa. Se vuoi tornare a Rut'theran in ippogrifo, parla con il maestro degli ippogrifi Caylais Moonfeather. Se vuoi prendere il traghetto, ne parte uno regolarmente dal molo a nord-ovest.", "{name}, sei <tornato/tornata> da Auberdine? Hai parlato con Laird?", "Molto interessante. I pesci qui sono grandi, ma non pensavo che la differenza di abbondanza tra qui e il continente fosse così grande. Deve esserci un motivo...\n\nBeh, grazie, {name}. Discuterò con gli abitanti del villaggio delle notizie che hai portato. Forse un giorno troveremo l'origine di questa stranezza. Ma fino ad allora ne raccoglieremo i benefici!", 0xba10c9cf, 0x9efa6697, 0x2381f0ae, 0x47a9c3c4, 0x4e30b81a, "....." },
  [6344] = { nil, "Parla con Nessa Shadowsong.", "Una mia amica, Nessa Shadowsong, è una mercante di pesce del villaggio di Rut'theran. Deve far arrivare un pacco a Darkshore e cerca qualcuno che la aiuti.\n\nSe ti interessa, per raggiungere Nessa devi prendere il portale di Darnassus per Rut'theran Village. Trovi il portale a ovest dei Temple Gardens.", nil, "Sì, mi serve un corriere che porti un pacco a Darkshore. Mi aiuterai?", nil, 0x0db93fa5, 0x3d0373e4, nil, 0xaae17e8e, "m..m." },
  [6387] = { "Studenti d'onore", "Porta la Brock's List a Thorgrum Borrelson, a Thelsamar.", "Vedo molti giovani nani alla mia porta, ansiosi di imparare il mestiere del minatore. E se c'è una cosa di cui un minatore ha bisogno più di ogni altra, è un piccone!\n\nHo un elenco di studenti di estrazione che hanno ottenuto voti alti nelle lezioni e si sono meritati un piccone d'onore. Porta il mio elenco a Golnir Bouldertoe, a Ironforge. Lui preparerà i picconi.\n\nIl modo più rapido per arrivare a Ironforge è in grifone, quindi porta l'elenco al nostro maestro dei grifoni, Thorgrum Borrelson, e parlagli del trasporto per Ironforge.", "Ne hai già abbastanza di Thelsamar? Sei <pronto/pronta> a partire per un'altra città?", "Devi portarlo a Ironforge, eh? Per una piccola somma posso metterti in groppa a uno dei miei grifoni, e ti porterà là. Che ne dici?", 0x24e749d7, 0xf62403c1, 0x57e23adf, 0x093769d9, 0xedf1dc2f, "....." },
  [6391] = { "In volo verso Ironforge", "Compra un volo in grifone per Ironforge dal maestro dei grifoni Thorgrum Borrelson, poi porta la Brock's List a Golnir Bouldertoe, a Ironforge.", "Per poche monete, uno dei miei grifoni ti porterà a Ironforge. Da lì, consegna la lista di Brock a Golnir Bouldertoe. Lo troverai nella Deep Mountain Mining Guild. Si trova nel Great Forge District di Ironforge, proprio dove ti lascerà il mio grifone!\n\nParlami di nuovo quando sarai <pronto/pronta> per il viaggio.", "Cosa posso fare per voi, <signore/signora>?", "Ah, l'ultima lista dei migliori allievi di Brock. Ho un lotto di picconi onorari pronti. Devo solo incidere i nomi degli studenti...", 0xd28081ed, 0x0477c979, 0x2cfa2e26, 0x92c650dc, 0xe778e783, ".....", nil, nil, nil, 0xd6deda79, nil },
  [6561] = { "Malvagità a Blackfathom", nil, nil, nil, nil, 0x43ec82c9, nil, nil, nil, nil, ".mmmm" },
  [6626] = { "Un'orda di malvagi", "Uccidi 8 Razorfen Battleguard, 8 Razorfen Thornweaver e 8 Death's Head Cultist e torna da Myriam Moonsinger, vicino all'ingresso di Razorfen Downs.", "Da quel che ho visto, i Forsaken non trasmettono la loro... malattia. Questo diplomatico sembra concedere la non morte ai suoi aspiranti seguaci. Comincio a pensare che sia uno della Scourge.\n\nPer ora, però, non mi preoccupa lui, ma le schiere crescenti intorno a lui. Strisciano fuori dall'ombra ogni giorno, quasi implorandolo di dar loro più potere.\n\nNon sono abbastanza potente da affrontarli da sola, {name}. Che ne dici? Te la senti di andare a caccia?", "Come va la caccia, {name}? Vedere anche solo questo piccolo saggio del potere di questo diplomatico mi toglie ogni dubbio: la Scourge è una delle più grandi minacce che questo mondo abbia mai visto.", "Grazie, {name}! Il lavoro che hai fatto sarà di grande aiuto, ne sono certa.\n\nContinuerò a studiare questo diplomatico e il resto dei quilboar qui. Se cerchi avventure più grandi, troverei qualche amico e andrei nella grotta che sembra le fauci di un grande cinghiale, proprio laggiù. Sono sicura che una volta dentro troverai sfide più grandi da affrontare.", 0xa6ad637c, 0x78151438, 0x50ddd7c3, 0x416675bc, 0x196700d7, "....." },
  [6721] = { "La via del cacciatore", "Parla con Dazalar, a Dolanaar.", "Salve, giovane <cacciatore/cacciatrice>. Mi sembri abbastanza abile da gestire una bestia e addestrarla come tua compagna.\n\nDevi andare da Dazalar, a Dolanaar. Lui può metterti sulla strada per guadagnarti un animale tutto tuo.", nil, "Sì, è il momento, {class}.", 0xe59cef47, 0xacb77771, 0x57c4b6af, nil, 0xca92f25f, "...m." },
  [6722] = { "La via del cacciatore", "Parla con Dazalar, a Dolanaar.", "Salve, giovane <cacciatore/cacciatrice>. Mi sembri abbastanza abile da gestire una bestia e addestrarla come tua compagna.\n\nDevi andare da Dazalar, a Dolanaar. Lui può metterti sulla strada per guadagnarti un animale tutto tuo.", nil, nil, 0xe59cef47, 0xacb77771, 0x57c4b6af, nil, nil, "...mm" },
  [6761] = { "La nuova frontiera", "Parla con Mathrengyl Bearwalker, nel Cenarion Enclave di Darnassus.", "Ho affidato al mio secondo, Mathrengyl Bearwalker, la richiesta di aiuto di Moonglade. Parlane con lui, non con me.\n\nLascia che ti dia un consiglio... amichevole. Sono io che ci ho guidati fuori dalle tenebre, non il Cenarion Circle di Moonglade, quando per la nostra razza tutto era perduto. Teldrassil ci dà a tutti una nuova vita! Loro vorrebbero farti credere il contrario, e credere alla loro propaganda sarebbe da sciocchi.\n\nLascio a te decidere se sei <uno/una> <sciocco/sciocca> o no.", nil, "Sì {class}, grazie per essere <venuto/venuta>. Mi scuso per il malinteso... l'aria è densa di sfiducia tra l'arcidruido qui e Keeper Remulos a Moonglade. Ciascuno sospetta l'altro di imbrogli, e il fatto che le strane corruzioni di Teldrassil continuino senza sosta resta un problema. Non aiuta certo a placare la sfiducia.\n\nComunque sia, il nostro dovere verso il Cenarion Circle resta... anche se chi lo guida può non essere d'accordo.", 0x980efd04, 0xc843270f, 0x3b0ebeda, nil, 0x1a73fafa, "...m." },
  [6762] = { nil, "Parla con Rabine Saturna nel villaggio di Nighthaven, a Moonglade. Moonglade si trova tra Felwood e Winterspring, raggiungibile con un sentiero che parte dalla Timbermaw Hold.", "Per questo compito, il maggiordomo di Keeper Remulos a Moonglade, Rabine Saturna, cerca aiuto per esplorare le vaste terre desolate molto a ovest di Tanaris... e ancora più a ovest di Un'Goro. Dovresti trovarlo a Nighthaven, il villaggio principale di Moonglade.\n\nAnche se il tuo lavoro sarà senza dubbio di enorme beneficio per tutti noi, ti consiglio di muoverti con cautela. Ci sono tensioni tra Darnassus e Moonglade... tensioni che col tempo potrebbero crescere.", nil, "Sono Rabine Saturna, e a nome di Keeper Remulos e di tutti gli abitanti di questa radura sacra ti do il benvenuto.\n\nApprezzo il tuo interesse e la tua voglia di aiutare il Cenarion Circle. So anche che l'arcidruido di Darnassus ti ha espresso il suo disappunto per l'aiuto che ci dai. Puoi stare <tranquillo/tranquilla>: è per il bene comune, e sarai al sicuro da qualunque ritorsione sconsiderata di cui potresti essere bersaglio.\n\nQui sei tra amici, {name}.", nil, 0x2d1faec5, 0xf45142aa, nil, 0xbe6728af, "m..m." },
  [6845] = { "Svelare i segreti del passato", "Parla con Rabine Saturna nel villaggio di Nighthaven, a Moonglade.", "Comunque, dovresti ripassare da me abbastanza presto... sempre che tu voglia sapere cosa c'era qui dentro. Appena scoprirò di cosa si tratta, e se è davvero un libro, sarò felice di condividere quelle informazioni con te.\n\nNel frattempo, io passerei dalla madre della tana di questo piccolo accampamento di orsi, Rabine. Di sicuro vorrà sapere che follie hai combinato. Non far mai aspettare la madre della tana, {name}... a meno che tu non voglia essere <ricoperto/ricoperta> di miele.\n\nÈ già successo, fidati.", nil, "Ah, {name}, speravo che saresti <passato/passata>. Sono lieto di vederti in salute.\n\nMi è stato detto che saresti <rientrato/rientrata> dal campo, e volevo esprimerti personalmente la gratitudine del Cenarion Circle per l'aiuto che ci hai dato finora. Senza dubbio ci sono altri segreti da svelare a Silithus; ciò che hai consegnato a Umber dovrebbe rivelarsi molto interessante una volta decifrato. Ti prego, accetta questo come segno del nostro continuo apprezzamento per il tuo aiuto.\n\nGrazie, {class} dal cuore generoso.", 0xeabb3200, 0x5071bbe4, 0x9bb68a79, nil, 0xa03acc7f, "...m." },
  [6981] = { nil, "Recati a Ratchet per trovare qualcuno che possa dirti di più sul frammento luminoso.\n\nPoi consegna il frammento come ti verrà indicato.", "Il frammento è di un verde brillante e, sebbene solido, sotto la superficie sembra vorticare del fumo. Non puoi fare a meno di fissare le profondità del cristallo; al tempo stesso, sai che c'è qualcosa di molto inquietante in esso.\n\nForse dovresti vedere se qualcuno a Ratchet può dirti di più su questo strano frammento.", "Salve, {race}. Cosa posso fare per te?", "Oh... non ho mai visto niente del genere...", nil, 0x9db6d7f4, 0xf1eddfb4, 0x60aba222, 0xcb5cd7b9, "m...." },
})
